const resp = $input.first().json;
if (resp.statusCode !== 200) return [];
const body = typeof resp.body === 'string' ? resp.body : (typeof resp.data === 'string' ? resp.data : '');

// Cutshort's own lastmod values are real per-job timestamps (unlike Hirist's,
// which are bulk-touched on every site rebuild -- see Parse Hirist Sitemap).
// Only entries updated in the last 24h keep daily volume sane.
const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const re = /<url>\s*<loc>([^<]+)<\/loc>\s*<lastmod>([^<]+)<\/lastmod>/g;
const out = [];
let m;
while ((m = re.exec(body)) !== null) {
  const [, loc, lastmod] = m;
  const t = Date.parse(lastmod);
  if (!isNaN(t) && t > cutoff) {
    out.push({ json: { source: 'cutshort', url: loc } });
  }
}
return out;

const resp = $input.first().json;
if (resp.statusCode !== 200) return [];
const body = typeof resp.body === 'string' ? resp.body : (typeof resp.data === 'string' ? resp.data : '');

// Hirist's lastmod is bulk-touched on every sitemap regen (all entries share
// the same timestamp) -- not usable for date filtering, unlike Cutshort's.
// Volume control here relies entirely on the slug keyword prefilter plus the
// already-collected check downstream, not on recency.
const re = /<loc>([^<]+)<\/loc>/g;
const out = [];
let m;
while ((m = re.exec(body)) !== null) {
  out.push({ json: { source: 'hirist', url: m[1] } });
}
return out;

// Coarse, lossy pre-fetch filter driven by the URL slug alone (company/
// role/location text embedded in the job URL) -- NOT the same guarantee as
// WF-2's conservative "ambiguous always passes" prefilter. This one exists
// purely to control volume before an expensive fetch+LLM step (Cutshort
// alone has ~4-5k new postings/day, almost none of them internships), so
// real recall risk is accepted here deliberately. WF-2's own prefilter and
// LLM scoring still run on whatever survives this.
const prefs = ($('Call WF-L0').first().json.config) || {};
const excludeTerms = ((prefs.exclude || {}).role_keywords || []).map(s => s.toLowerCase());

const SENIORITY_SIGNALS = ['intern', 'internship', 'fresher', 'trainee', 'graduate', 'campus', 'entry-level', 'entry level', 'junior', '0-1-years', '0-1-yrs'];
const ROLE_SIGNALS = ['software', 'backend', 'frontend', 'full-stack', 'fullstack', 'developer', 'engineer', 'sde', 'data', 'machine-learning', 'machine learning', 'ml-', 'ai-', ' ai ', 'python', 'analyst'];

// Hard per-run cap. Hirist's sitemap has no usable date field to narrow by
// (see Parse Hirist Sitemap), so without this a single run could produce
// hundreds of candidates -- each Hirist fetch alone costs a mandatory 10s
// wait, so this bounds both real Anthropic spend and wall-clock time per
// run to something a first, unattended daily run should never exceed.
// Raise deliberately once real daily volume after prefiltering is known.
const MAX_CANDIDATES_PER_RUN = 30;

const matched = $input.all().filter(item => {
  const slug = decodeURIComponent(item.json.url).toLowerCase().replace(/[-_]/g, ' ');
  if (excludeTerms.some(t => slug.includes(t))) return false;
  const hasSeniority = SENIORITY_SIGNALS.some(t => slug.includes(t.replace(/-/g, ' ')));
  const hasRole = ROLE_SIGNALS.some(t => slug.includes(t.replace(/-/g, ' ')));
  return hasSeniority && hasRole;
});

return matched.slice(0, MAX_CANDIDATES_PER_RUN);

const src = $('Filter Already Collected').all()[$itemIndex].json;
const resp = $json;

if (resp.statusCode !== 200) {
  return { json: { source: src.source, url: src.url, fetch_failed: true } };
}

const raw = typeof resp.body === 'string' ? resp.body : (typeof resp.data === 'string' ? resp.data : '');
let text = raw
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ')
  .trim();
text = text.slice(0, 6000);

return { json: { source: src.source, url: src.url, page_text: text } };

const ctx = $('Strip HTML For LLM').all()[$itemIndex].json;
if (ctx.fetch_failed) return { json: { skip: true } };

const content = $json.content || [];
const textBlock = content.find(b => b.type === 'text');
const rawText = textBlock ? textBlock.text : '';

let parsed;
try {
  const cleaned = (rawText || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return { json: { skip: true } };
}

if (parsed.not_a_posting || !parsed.company || !parsed.role) {
  return { json: { skip: true } };
}

return {
  json: {
    skip: false,
    company: parsed.company,
    role: parsed.role,
    location: parsed.location || null,
    employment_type: parsed.employment_type || null,
    apply_url: ctx.url,
    source: ctx.source,
    source_id: null,
    description: parsed.description || null,
    posted_date: parsed.posted_date || null
  }
};

const dedupOutputs = $input.all();
const originals = $('Call WF-L1').all();
const toScore = [];
for (let i = 0; i < dedupOutputs.length; i++) {
  if (dedupOutputs[i].json.was_inserted === true) {
    toScore.push({ json: originals[i].json });
  }
}
return toScore;

let candidates = 0, prefiltered = 0;
try { candidates = $('Merge Sitemaps').all().length; } catch (e) {}
try { prefiltered = $('Slug Keyword Prefilter').all().length; } catch (e) {}
const items = $input.all();
const fetched = items.length;
const inserted = items.filter(i => i.json.was_inserted === true).length;
return [{ json: { candidates, prefiltered, fetched, new_count: inserted } }];
